export function getT4Ending(score) {
  const max = 100 + 30 * 15; // 550
  const pct = score / max;
  if (pct >= 0.85) return { title: 'Systems Architect', summary: 'You think in tokens, components, and governance models. You understand how design decisions propagate, how systems evolve, and how to build for teams you\'ve never met.' };
  if (pct >= 0.65) return { title: 'Systems Thinker', summary: 'You\'ve internalised the vocabulary and principles of design systems. Your work reduces duplication, improves consistency, and creates leverage for everyone who builds after you.' };
  if (pct >= 0.45) return { title: 'Pattern Recogniser', summary: 'You\'re developing your systems instincts. Keep asking: "How many times does this exist? Should it be a token? Should it be shared?" The habit of systems thinking is forming.' };
  return { title: 'Systems Foundations Needed', summary: 'Design systems are learnable. Start with tokens — they\'re the highest-value, lowest-complexity starting point. Build from there.' };
}
